INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62584857', 62584857, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'PUSAT DATA DAN INFORMASI KELUARGA', 'Penyediaan Tenaga Ahli Project Manager Rancangan Pengembangan Sistem Informasi Evaluasi Pendataan Keluarga Satu Pintu Manual', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 75487500, 'September 2026', 'APBD', 1, 1, '1 orang x 3 bulan', 'Mengembangkan desain metodologi pendataan keluarga satu pintu Membuatroadmap pengembangan pendataan keluarga satu pintu Membuat analisis dan kebijakan yang mempunyai manfaat dan berguna dalam perumusan kebijakan di Pemprov DKI Jakarta Mempertanggungjawabkan proses analisa, pengolahan data untuk mendapatkan informasi baru sebagai basis dalam pengembilan kebijakan Mempertanggungjawabkan perencanaan dan pengembangan program,monitoring dan evaluasi program Mempertanggungjawabkan identifikasi data, metodologi analisis, dan memaparkan analisis terhadap suatu isu yang ada Melakukan pemadanan dan analisa kebutuhan instrumen pada perangkat daerah yang dikembangkan menjadi instrumen pendataan keluarga satu pintu Melakukan diskusi dengan perangkat daerah terkait kebutuhan data dan sinkronisasi pertanyaan yang ada dalam instrumen pendataan keluarga satu pintu Melakukan koordinasi dengan Tim Penggerak PKK dalam rangka memastikan kebutuhan data perangkat daerah dapat terakomodir oleh Kader Dasawisma Mempertanggungjawabkan finalisasi instrumen pendataan keluarga satu pintu Berkoordinasi dengan tenaga ahli pengembangan sistem untuk memastikan pertanyaan dalam instrumen sudah masuk dalam aplikasi dikuti dengan proses validasi pertanyaan Mengembangkan rencana tabulasi databerdasarkan hasil assestment kebutuhan informasi Melakukan kompilasi dan koordinasi dalam rangka pemutakhiran data Kader Dasawisma serta melakukan analisis sebaran dan cakupan kader dasawisma dalam suatu wilayah Mengembangkan modul pelatihan pendataan keluarga satu pintu Berperan aktif dalam melakukan pendampingan dan pelatihan terhadap kader dasawisma Berperan aktif dalam pendampingan pengembangan produk hukum terkait pendataan keluarga satu pintu Melakukan pendampingan terkait sosialisasi pendataan keluarga satu pintu Membuat dokumen tertulis kebijakan dan SOP teknis tata kelola pendataan dari perencanaan hingga evaluasi Melakukan manajemen pengelolaan proyek pendataan', 'Pendidikan diutamakan S2 jurusan Statistik, Jurusan Statistik/ Ilmu Statistik terapan lainya (Ekonometri, Psikometri, Biostatistik, Epidemilogi) ; Memiliki pengalaman kerja 13 tahun sebagai Data analyst Memiliki pengalaman menjadi koordinator survei Memiliki pengalaman mengerjakan manajemen data survei besar Memiliki pengalaman penulisan laporan hasil survei Memiliki pengetahuan yang kuat terkait metodologi penelitian Memiliki logika yang kuat dalam menganalisa data dan menyajikannya secata tepat Menguasai pengetahuan dalam mengunakan aplikasi statistik (SPSS, STATA, SAS, dll) Memahami konsep database Mampu melakukan pembuatan jurnal ilmiah Memiliki kemampuan menjelaskan hasil analisis Memiliki kemampuan berkoordinasi dengan team Diutamakan pernah mengikuti pelatihan ISO 27001 dan ISO 20000-1:2018', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 680585);
