INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62584766', 62584766, 'analyze_legacy', 'Kota Balikpapan', 'kabkota', 'UPTD-RUMAH SAKIT UMUM DAERAH', 'Belanja Tagihan Internet', 'Jasa Lainnya', 'E-Purchasing', 'Kalimantan Timur, Balikpapan (Kota)', 568906000, 'December 2025', 'BLUD', 1, 1, '1 Paket', 'Penyediaan layanan koneksi internet yang stabil, aman, dan berkelanjutan untuk mendukung operasional dan pelayanan RSUD Beriman Balikpapan, meliputi penyediaan bandwidth sesuai kebutuhan, instalasi dan konfigurasi perangkat jaringan, pemeliharaan dan monitoring layanan, penanganan gangguan (troubleshooting), serta dukungan teknis selama masa kontrak agar layanan internet berfungsi optimal sesuai standar layanan (SLA) yang ditetapkan.', 'A. Ruang Lingkup Pekerjaan Paket pekerjaan Jasa Internet adalah penyediaan layanan koneksi internet yang andal, aman, dan berkelanjutan untuk mendukung operasional, sistem informasi, dan pelayanan di RSUD Beriman Balikpapan, termasuk fasilitas instalasi, konfigurasi, pemeliharaan, dan dukungan teknis selama masa kontrak. B. Lingkup dan Uraian Pekerjaan - Menyediakan layanan koneksi internet dengan kapasitas bandwidth sesuai kebutuhan instansi. - Melaksanakan instalasi dan konfigurasi jaringan internet hingga berfungsi optimal. - Menjamin ketersediaan layanan internet selama masa kontrak. - Melakukan pemeliharaan dan monitoring jaringan secara berkala. - Menyediakan layanan dukungan teknis dan penanganan gangguan (troubleshooting). - Menjaga keamanan jaringan sesuai ketentuan yang berlaku. - Menyampaikan laporan layanan internet secara berkala bila diperlukan. C. Standar Layanan / Indikator Kinerja (SLA) - Tingkat ketersediaan layanan (uptime) minimal 99%. - Waktu respon penanganan gangguan maksimal 1 x 24 jam. - Kualitas koneksi stabil sesuai bandwidth yang diperjanjikan. - Layanan internet aktif dan dapat digunakan sesuai jam operasional instansi. D. Output Pekerjaan - Layanan internet aktif, stabil, dan berfungsi dengan baik. - Dukungan teknis tersedia selama masa kontrak. - Operasional dan pelayanan instansi berjalan tanpa hambatan jaringan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 683682);
