INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63148418', 63148418, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Individual Penyusunan Kebijakan Pembangunan Kewilayahan Kegiatan Koordinasi Proses Aksesi Indonesia Ke OECD Bidang Pembangunan Kewilayahan Direktorat Tata Ruang, Perkotaan, Pertanahan, Dan Penanggulangan Bencana', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 180000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', '1. Memberikan dukungan keahlian dan analisis kebijakan dalam penyusunan Accession Readiness Report bidang Regional Development, termasuk asesmen kesiapan Indonesia terhadap prinsip-prinsip kunci Regional Development Policy Committee (RDPC) serta identifikasi keselarasan, kesenjangan (gap), dan isu strategis kebijakan; 2. Memberikan dukungan dalam proses identifikasi, pengumpulan, pemetaan, dan analisis data dan informasi pembangunan regional, termasuk indikator teritorial pada berbagai tingkat wilayah, sebagai bahan asesmen kesiapan kebijakan Indonesia terhadap prinsip RDPC OECD.; 3. Membantu mengawal dan memfasilitasi proses koordinasi teknis dengan OECD, kementerian/lembaga terkait, serta pemangku kepentingan lainnya, dalam rangka mendukung tahapan technical review di bawah Regional Development Policy Committee (RDPC) dan Working Parties terkait; 4. Membantu penyiapan bahan substansi dan dukungan teknis untuk kegiatan diskusi, webinar/technical information meeting, fact-finding mission, serta pertemuan RDPC Week dan sesi-sesi lain dalam rangkaian technical review proses aksesi Indonesia ke OECD; 5. Membantu pelaporan perkembangan proses aksesi, termasuk pemutakhiran matriks isu– respons, kuesioner technical review, dokumentasi hasil kegiatan, serta penyusunan laporan pelaksanaan sebagai bahan pengambilan keputusan dan tindak lanjut kebijakan; 6. Bertanggungjawab atas selesainya pekerjaan hingga dihasilkan laporan yang dapat diterima oleh pihak pemberi tugas dengan hasil yang memuaskan; serta', '1. Merupakan Jasa Konsultan Individual dalam negeri, dibuktikan dengan identitas kewarganegaraan Indonesia (Kartu Tanda Penduduk); 2. Memiliki Nomor Pokok Wajib Pajak (NPWP) dan berstatus valid Konfirmasi Status Wajib Pajak (KSWP); 3. Memiliki pendidikan minimal Strata-2 (S2) di bidang Perencanaan Wilayah dan Kota, Ekonomi Regional, Kebijakan Publik, Hubungan Internasional, Studi Pembangunan, atau Geografi, atau bidang lain yang relevan dengan pembangunan kewilayahan (dibuktikan dengan ijazah); 4. Memiliki pengalaman kerja minimal 5 (lima) tahun di bidang perencanaan dan/atau kebijakan pembangunan wilayah dan perkotaan, termasuk pengalaman dalam analisis kebijakan, koordinasi lintas pemangku kepentingan, serta monitoring dan evaluasi program/proyek (dibuktikan dengan surat referensi dan/atau kontrak pekerjaan); 5. Memiliki pengalaman pekerjaan sejenis dengan nilai pekerjaan tertinggi dalam kurun waktu 3 (tiga) tahun terakhir paling kurang 50% (lima puluh persen) dari nilai HPS/Pagu Anggaran, sesuai ketentuan pengadaan yang berlaku; 6. Memiliki pengalaman dalam analisis data dan informasi pembangunan kewilayahan, baik kualitatif maupun kuantitatif, termasuk penggunaan data dan indikator teritorial, yang dibuktikan melalui hasil tulisan, laporan analisis, atau dokumen resmi lainnya;', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 687433);
